function* contarAteTres() {
  console.log('início');
  yield 1;
  console.log('depois do primeiro yield');
  yield 2;
  yield 3;
  console.log('fim');
}

const gerador = contarAteTres();

console.log(gerador.next());
// início
// { value: 1, done: false }

console.log(gerador.next());
// depois do primeiro yield
// { value: 2, done: false }

console.log(gerador.next());
// { value: 3, done: false }

console.log(gerador.next());
// fim
// { value: undefined, done: true }

class ListaDeTarefas {
  #itens = [];

  adicionar(tarefa) {
    this.#itens.push(tarefa);
  }

  *[Symbol.iterator]() {
    for (const tarefa of this.#itens) {
      yield tarefa;
    }
  }
}

const tarefas = new ListaDeTarefas();
tarefas.adicionar('estudar generators');
tarefas.adicionar('praticar yield*');

for (const tarefa of tarefas) {
  console.log(tarefa);
}
// estudar generators
// praticar yield*

function* percorrerNos(no) {
  yield no.valor;
  for (const filho of no.filhos) {
    yield* percorrerNos(filho);
  }
}

const arvore = {
  valor: 'raiz',
  filhos: [
    { valor: 'a', filhos: [{ valor: 'a1', filhos: [] }] },
    { valor: 'b', filhos: [] },
  ],
};

console.log([...percorrerNos(arvore)]); // ['raiz', 'a', 'a1', 'b']

function* somador() {
  let total = 0;
  while (true) {
    const incremento = yield total;
    total += incremento;
  }
}

const soma = somador();
console.log(soma.next().value);    // 0 (arranca o generator; um argumento aqui seria ignorado)
console.log(soma.next(5).value);   // 5
console.log(soma.next(10).value);  // 15
console.log(soma.next(-2).value);  // 13

function* naturais() {
  let n = 1;
  while (true) {
    yield n;
    n++;
  }
}

function tomar(gerador, quantidade) {
  const resultado = [];
  for (const valor of gerador) {
    resultado.push(valor);
    if (resultado.length === quantidade) break;
  }
  return resultado;
}

console.log(tomar(naturais(), 5)); // [1, 2, 3, 4, 5]

function* semaforo() {
  let cor = 'vermelho';
  while (true) {
    const evento = yield cor;
    if (cor === 'vermelho' && evento === 'avancar') {
      cor = 'verde';
    } else if (cor === 'verde' && evento === 'avancar') {
      cor = 'amarelo';
    } else if (cor === 'amarelo' && evento === 'avancar') {
      cor = 'vermelho';
    }
  }
}

const luz = semaforo();
console.log(luz.next().value);          // 'vermelho'
console.log(luz.next('avancar').value); // 'verde'
console.log(luz.next('avancar').value); // 'amarelo'
console.log(luz.next('avancar').value); // 'vermelho'

