function* contarAte(maximo) {
  for (let n = 1; n <= maximo; n++) {
    yield n;
  }
}

for (const valor of contarAte(5)) {
  console.log(valor);
}

function* naturais() {
  let n = 1;
  while (true) {
    yield n;
    n++;
  }
}

function tomar(gerador, quantidade) {
  const resultado = [];
  for (let i = 0; i < quantidade; i++) {
    const { value, done } = gerador.next();
    if (done) break;
    resultado.push(value);
  }
  return resultado;
}

console.log(tomar(naturais(), 5)); // [1, 2, 3, 4, 5]

function* tarefasUrgentes() {
  yield 'rever pedido';
  yield 'responder cliente';
}

function* tarefasNormais() {
  yield 'arquivar email';
  yield 'atualizar agenda';
}

function* todasAsTarefas() {
  yield* tarefasUrgentes();
  yield* tarefasNormais();
}

for (const tarefa of todasAsTarefas()) {
  console.log(tarefa);
}

function* estadoPedido() {
  let estado = 'pendente';
  while (true) {
    const evento = yield estado;
    if (estado === 'pendente' && evento === 'pagar') {
      estado = 'pago';
    } else if (estado === 'pago' && evento === 'enviar') {
      estado = 'enviado';
    } else if (estado === 'enviado' && evento === 'entregar') {
      estado = 'entregue';
    }
    // eventos que não correspondem a uma transição válida são ignorados
  }
}

const pedido = estadoPedido();
console.log(pedido.next().value);           // 'pendente'
console.log(pedido.next('pagar').value);    // 'pago'
console.log(pedido.next('enviar').value);   // 'enviado'
console.log(pedido.next('entregar').value); // 'entregue'
